evals.prompt:
My Chrome extension's popup sends a message to the background script but never gets a response back. Here's my code:

background.js:
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === 'FETCH_DATA') {
    fetch('https://api.example.com/data').then(data => sendResponse(data));
  }
});

popup.js:
chrome.runtime.sendMessage({ type: 'FETCH_DATA' }, (response) => {
  console.log('Got response:', response);
});

The console.log never fires. What's wrong, and how do I fix it? Also, are there any other message-passing anti-patterns in this code?

Review this Chrome extension code for quality issues, security problems, and MV3 violations. List everything wrong and how to fix each one.

manifest.json:
{
  "manifest_version": 3,
  "name": "Page Helper",
  "permissions": ["*://*/*"],
  "background": { "service_worker": "bg.js" },
  "content_scripts": [{
    "matches": ["<all_urls>"],
    "js": ["content.js"]
  }]
}

content.js:
function doit() {
  var data = document.querySelectorAll('.item');
  var result = [];
  for (var i = 0; i < data.length; i++) {
    var x = data[i];
    var url = x.getAttribute('data-url');
    if (url) result.push(url);
  }
  chrome.runtime.sendMessage({type:'SAVE',items:result});
}

bg.js:
var items = [];
chrome.runtime.onMessage.addListener(function(m, s, r) {
  if (m.type == 'SAVE') {
    items = items.concat(m.items);
    chrome.storage.local.set({data: items});
    r({ok: true});
  }
});
setInterval(function() { console.log('alive', items.length); }, 1000);
